def transform(grid):
    """Project edge-row color sequences onto rows containing matching markers."""
    h, w = len(grid), len(grid[0])
    templates = _runs(grid[0]) + _runs(grid[-1])
    out = [row[:] for row in grid]
    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            matches = [seq for seq in templates if color in seq]
            if not matches:
                continue
            seq = matches[0]
            anchor = seq.index(color)
            start = c - anchor
            for i, value in enumerate(seq):
                target = start + i
                if 0 <= target < w:
